/* Pure analytical functions shared by the UI and dependency-free Node tests. */
(function(root){
'use strict';
const mean=a=>a.length?a.reduce((s,v)=>s+v,0)/a.length:null;
const median=a=>{if(!a.length)return null;const b=[...a].sort((x,y)=>x-y),i=Math.floor(b.length/2);return b.length%2?b[i]:(b[i-1]+b[i])/2;};
const trade=r=>r.side==='YES'?[r.probability,r.outcome]:[1-r.probability,1-r.outcome];
function wilson(w,n){if(!n)return null;const z=1.96,p=w/n,c=(p+z*z/(2*n))/(1+z*z/n),h=z*Math.sqrt(p*(1-p)/n+z*z/(4*n*n))/(1+z*z/n);return [Math.max(0,c-h),Math.min(1,c+h)];}
function summary(rows){const v=rows.map(trade),p=v.map(([cost,win])=>win-cost),wins=v.reduce((s,r)=>s+r[1],0);return {n:rows.length,win_rate:rows.length?wins/rows.length:null,mean_return:mean(p),median_return:median(p),brier:mean(rows.map(r=>(r.probability-r.outcome)**2)),ci:wilson(wins,rows.length)};}
function calibration(rows,bins=10){const groups=new Map();for(const r of rows){const b=Math.min(bins-1,Math.floor(r.probability*bins));if(!groups.has(b))groups.set(b,[]);groups.get(b).push(r);}return [...groups].sort((a,b)=>a[0]-b[0]).map(([bucket,rs])=>({bucket,low:bucket/bins,high:(bucket+1)/bins,n:rs.length,expected:mean(rs.map(r=>r.probability)),observed:mean(rs.map(r=>r.outcome)),ci:wilson(rs.reduce((s,r)=>s+r.outcome,0),rs.length)}));}
const specs={probability:{label:'YES probability',cuts:[.2,.4,.6,.8],labels:['< 20%','20–40%','40–60%','60–80%','≥ 80%']},ttx_minutes:{label:'Time to expiry',cuts:[5,10],labels:['< 5 min','5–10 min','≥ 10 min']},atr:{label:'ATR',cuts:[100,175],labels:['< 100','100–175','≥ 175']},normalized_distance:{label:'Normalized distance',cuts:[-1,0,1],labels:['< −1','−1 to 0','0 to 1','≥ 1']},momentum:{label:'Momentum',cuts:[-.5,0,.5],labels:['< −0.5','−0.5 to 0','0 to 0.5','≥ 0.5']},session:{label:'Session (UTC)'},side:{label:'Side'},weekday:{label:'Weekday (UTC)'}};
function bucket(r,key){const spec=specs[key];if(!spec)throw Error('Feature not allowed');if(!spec.cuts)return String(r[key]);let i=spec.cuts.findIndex(c=>r[key]<c);if(i<0)i=spec.cuts.length;return spec.labels[i];}
function groups(rows,key){const spec=specs[key],keys=spec.labels||[...new Set(rows.map(r=>r[key]))].sort();return keys.map(label=>{const sample=rows.filter(r=>bucket(r,key)===label),research=sample.filter(r=>r.period==='research'),test=sample.filter(r=>r.period==='test');const a=summary(research),b=summary(test);return {label,rows:sample,research:a,test:b,status:a.n<30||b.n<30?'Needs more data':Math.sign(a.mean_return)!==Math.sign(b.mean_return)?'Direction changed':'Same direction · unconfirmed'};});}
function execution(rows,fee=1,slippage=1,fill=.9){if(fee<0||slippage<0||fill<0||fill>1)throw Error('Invalid execution assumptions');const eligible=rows.filter(r=>trade(r)[0]+slippage/100<1),gross=rows.reduce((s,r)=>s+trade(r)[1]-trade(r)[0],0),net=eligible.reduce((s,r)=>s+trade(r)[1]-trade(r)[0]-(fee+slippage)/100,0)*fill;return {attempts:rows.length,eligible:eligible.length,gross,net,expected_fills:eligible.length*fill,mean_net:rows.length?net/rows.length:null};}
function lossStreaks(rows){let streak=0;const counts={};for(const r of [...rows].sort((a,b)=>a.timestamp.localeCompare(b.timestamp))){if(trade(r)[1]===0)streak++;else if(streak){counts[streak]=(counts[streak]||0)+1;streak=0;}}if(streak)counts[streak]=(counts[streak]||0)+1;return Object.entries(counts).map(([length,count])=>({length:+length,count}));}
function csvCell(value){let s=String(value??'');if(/^[=+@\-\t\r]/.test(s))s="'"+s;return '"'+s.replaceAll('"','""')+'"';}
const api={mean,median,trade,wilson,summary,calibration,specs,bucket,groups,execution,lossStreaks,csvCell};
if(typeof module!=='undefined'&&module.exports)module.exports=api;else root.Analytics=api;
})(typeof window!=='undefined'?window:globalThis);
